// ---------------------------------------------------------------------------
// Mapa de actores de Apify, uno por fuente.
//
// Antes este workflow tenia un IF binario "Es Google Maps?": cualquier otra
// fuente caia en un noOp y la busqueda moria en silencio (el usuario veia
// "busqueda iniciada" y no llegaba nada). Ahora cada fuente declara su actor
// y como se le arma la entrada, y el nodo HTTP siguiente es uno solo.
//
// Para cambiar de actor: edita SOLO este mapa.
//   actor      -> id del actor en Apify (usuario~nombre)
//   confirmado -> false = todavia no verificado contra la cuenta de Apify.
//                 Se lanza un error claro en vez de gastar creditos con un
//                 actor que puede no existir o devolver otra forma de datos.
// ---------------------------------------------------------------------------
const ACTORES = {
  google_maps: {
    actor: 'compass~crawler-google-places',
    confirmado: true,
    input: (q) => ({
      searchStringsArray: [q.tipo],
      locationQuery: q.ciudad,
      maxCrawledPlacesPerSearch: q.max,
      language: 'es',
      scrapeContacts: true,
      scrapePlaceDetailPage: true,
    }),
  },
  google_web: {
    actor: 'apify~google-search-scraper',
    confirmado: true,
    input: (q) => ({
      queries: q.ciudad ? (q.tipo + ' ' + q.ciudad) : q.tipo,
      resultsPerPage: Math.min(100, q.max),
      maxPagesPerQuery: 1,
      languageCode: 'es',
    }),
  },
  instagram: {
    actor: 'apify~instagram-scraper',
    confirmado: true,
    input: (q) => ({
      // `searchType: user` + `resultsType: details` devuelve PERFILES, no
      // publicaciones: un lead es una cuenta de negocio, no un post suelto.
      search: q.ciudad ? (q.tipo + ' ' + q.ciudad) : q.tipo,
      searchType: 'user',
      resultsType: 'details',
      resultsLimit: q.max,
      searchLimit: q.max,
    }),
  },
  facebook: {
    actor: 'apify~facebook-pages-scraper',
    confirmado: false,   // <-- confirmar el actor y su entrada en tu cuenta Apify
    input: (q) => ({
      searchQuery: q.ciudad ? (q.tipo + ' ' + q.ciudad) : q.tipo,
      maxPages: q.max,
    }),
  },
  linkedin: {
    actor: 'harvestapi~linkedin-company-search',
    confirmado: false,   // <-- LinkedIn no tiene actor oficial de Apify; confirmar cual usas
    input: (q) => ({
      searchQuery: q.tipo,
      locations: q.ciudad ? [q.ciudad] : [],
      maxItems: q.max,
    }),
  },
};

const body = ($input.first().json.body) || $input.first().json || {};

const tipo = (body.tipo_negocio || 'real estate agency').toString().trim() || 'real estate agency';
// La ciudad ya no se rellena por defecto: en redes sociales se busca por nicho
// o hashtag sin ubicacion, y meter "Miami, FL, USA" a la fuerza sesgaba la
// busqueda hacia un sitio que el usuario no habia pedido.
const ciudad = (body.ciudad || '').toString().trim();

let max = parseInt(body.max, 10);
if (isNaN(max)) max = 20;
max = Math.min(50, Math.max(1, max));

let fuente = (body.fuente || 'google_maps').toString().trim();
if (!ACTORES[fuente]) fuente = 'google_maps';

const cfg = ACTORES[fuente];
if (!cfg.confirmado) {
  throw new Error(
    'Fuente "' + fuente + '": el actor de Apify "' + cfg.actor + '" aun no esta ' +
    'confirmado. Verifica el id y la forma de su entrada en tu cuenta de Apify y ' +
    'pon confirmado: true en el nodo "Preparar Busqueda". No se ha gastado ningun credito.'
  );
}

// Google Maps SI necesita ubicacion: sin ella el actor rastrea el mundo entero.
if (fuente === 'google_maps' && !ciudad) {
  throw new Error('Google Maps requiere ciudad/ubicacion.');
}

const actorInput = cfg.input({ tipo, ciudad, max });

return [{ json: {
  fuente,
  actorId: cfg.actor,
  actorInput,
  consulta: ciudad ? (tipo + ' / ' + ciudad) : tipo,
  // `Log Busqueda` (search_logs) cuelga de este nodo y lee estos dos campos.
  tipo_negocio: tipo,
  ciudad,
} }];

// El resultado del import es la prueba de si el lote llego completo. Se deja
// visible en la ejecucion para no tener que abrir la base de datos.
const r = $json;
console.log(`[captacion] recibidos=${r.recibidos} insertados=${r.insertados} actualizados=${r.actualizados} descartados=${r.descartados}`);
if (r.descartados > 0) console.log('[captacion] descartados:', JSON.stringify(r.detalle));
return [{ json: r }];

// ---------------------------------------------------------------------------
// Cada actor de Apify devuelve una forma distinta. `importar_leads` (Supabase)
// entiende alias, pero no puede adivinar que en Instagram el nombre del
// negocio esta en `fullName` y la web en `externalUrl`, ni desanidar los
// `organicResults` de la busqueda web.
//
// Aqui se traduce cada fuente al vocabulario canonico que espera la funcion:
//   title, website, phone, email, city, address, profileUrl,
//   followersCount, biography, category
//
// Lo que no se reconoce se deja pasar tal cual: la funcion tiene sus propios
// alias y es preferible que llegue de mas a que se pierda.
// ---------------------------------------------------------------------------
const prep = $('Preparar Busqueda').first().json;
const fuente = prep.fuente || 'google_maps';
const crudo = $input.all().map((i) => i.json);

const limpio = (v) => (v === null || v === undefined || v === '' ? undefined : v);

function deGoogleWeb(items) {
  // El actor devuelve UN item por consulta con `organicResults` dentro.
  const salida = [];
  for (const it of items) {
    for (const r of it.organicResults || []) {
      if (!r.title) continue;
      salida.push({
        title: r.title,
        website: r.url,
        profileUrl: r.url,
        biography: limpio(r.description),
      });
    }
  }
  return salida;
}

function deInstagram(items) {
  return items
    .filter((it) => it.username || it.fullName)
    .map((it) => {
      const perfil = it.url || ('https://www.instagram.com/' + it.username + '/');
      return {
        title: it.fullName || it.username,
        profileUrl: perfil,
        instagram: perfil,
        website: limpio(it.externalUrl),
        // Instagram solo expone email/telefono en cuentas de empresa; cuando
        // no los da, suelen estar escritos en la bio y los rescata la Fase 2.
        email: limpio(it.businessEmail),
        phone: limpio(it.businessPhoneNumber),
        biography: limpio(it.biography),
        followersCount: it.followersCount,
        category: limpio(it.businessCategoryName),
      };
    });
}

function deFacebook(items) {
  return items
    .filter((it) => it.title || it.name)
    .map((it) => ({
      title: it.title || it.name,
      profileUrl: it.pageUrl || it.url,
      facebook: it.pageUrl || it.url,
      website: limpio(it.website),
      phone: limpio(it.phone),
      email: limpio(it.email),
      address: limpio(it.address),
      city: limpio(it.city),
      biography: limpio(it.intro || it.info),
      followersCount: it.followers || it.likes,
      category: limpio(Array.isArray(it.categories) ? it.categories[0] : it.categories),
    }));
}

function deLinkedIn(items) {
  return items
    .filter((it) => it.name || it.companyName || it.title)
    .map((it) => ({
      title: it.name || it.companyName || it.title,
      profileUrl: it.linkedinUrl || it.url,
      linkedin: it.linkedinUrl || it.url,
      website: limpio(it.websiteUrl || it.website),
      city: limpio(it.location || it.locality),
      category: limpio(it.industry),
      biography: limpio(it.description || it.tagline),
      followersCount: it.followerCount || it.followersCount,
    }));
}

const traductores = {
  google_maps: (items) => items,   // el vocabulario canonico ES el suyo
  google_web: deGoogleWeb,
  instagram: deInstagram,
  facebook: deFacebook,
  linkedin: deLinkedIn,
};

const lote = (traductores[fuente] || ((x) => x))(crudo);

// Un lote vacio NO es un error, pero tampoco puede pasar desapercibido: se
// deja constancia en el log y se sigue, para que `importar_leads` registre la
// busqueda en `lead_imports` con recibidos=0. Asi "no llego nada" queda
// distinguible de "no se ejecuto nada".
console.log('[captacion] fuente=' + fuente + ' crudo=' + crudo.length + ' normalizados=' + lote.length);

// Un unico paquete con el lote COMPLETO (igual que antes "Empaquetar Lote"):
// si se enviara item a item, un fallo intermedio dejaria la mitad de los leads
// fuera y sin rastro. Asi entra el lote entero o falla el lote entero, y en
// ambos casos queda registrado en lead_imports.
return [{ json: {
  p_lote: lote,
  p_fuente: fuente,
  p_consulta: prep.consulta,
} }];

const body = ($input.first().json.body) || $input.first().json || {};
const tipo = (body.tipo_negocio || 'real estate agency').toString().trim() || 'real estate agency';
const ciudad = (body.ciudad || 'Miami, FL, USA').toString().trim() || 'Miami, FL, USA';
let max = parseInt(body.max, 10);
if (isNaN(max)) max = 20;
max = Math.min(50, Math.max(1, max));

// `google_web` sigue en la lista porque el CRM lo ofrece, pero su rama no
// guarda nada (ver nodo "Fuente No Disponible"). Antes ejecutaba el actor de
// Apify, pagaba los creditos y tiraba el resultado: eso ya no pasa.
const fuentesValidas = ['google_maps', 'google_web', 'linkedin', 'instagram', 'facebook'];
let fuente = (body.fuente || 'google_maps').toString().trim();
if (!fuentesValidas.includes(fuente)) fuente = 'google_maps';

return [{ json: {
  searchStringsArray: [tipo],
  locationQuery: ciudad,
  maxCrawledPlacesPerSearch: max,
  language: 'en',
  tipo_negocio: tipo,
  ciudad,
  fuente,
  consulta: `${tipo} / ${ciudad}`
} }];

// Un unico paquete con el lote COMPLETO. Es deliberado: si se enviara item a
// item, un fallo intermedio dejaria la mitad de los leads fuera y sin rastro
// (el sintoma "Apify dice 10 y el CRM guarda 1"). Asi entra el lote entero o
// falla el lote entero, y en ambos casos queda registrado en lead_imports.
const lote = $input.all().map(i => i.json);
const prep = $('Preparar Busqueda').first().json;

return [{ json: {
  p_lote: lote,
  p_fuente: prep.fuente || 'google_maps',
  p_consulta: prep.consulta
} }];

// El resultado del import es la prueba de si el lote llego completo. Se deja
// visible en la ejecucion para no tener que abrir la base de datos.
const r = $json;
console.log(`[captacion] recibidos=${r.recibidos} insertados=${r.insertados} actualizados=${r.actualizados} descartados=${r.descartados}`);
if (r.descartados > 0) console.log('[captacion] descartados:', JSON.stringify(r.detalle));
return [{ json: r }];
